import * as React from "react";
import Loadable from "react-loadable";
import { plotlyConfig, plotlyLayout, plotlyProps } from '../../utils/plotly';

const Barplot = ({ data, height, xaxis = {}, yaxis = {} }) => {

  const Plot = Loadable({
    loader: () => import('react-plotly.js'),
    loading() {
      return (
        <div style={{ height, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div className="loader" />
        </div>
      );
    },
  });

  return (
    <div style={{ minHeight: height, padding: '0px 8px' }}>
      <Plot
        data={[
          {
            type: 'bar',
            orientation: 'h',
            texttemplate: '%{text}',
            textposition: 'inside',
            insidetextanchor: 'end',
            insidetextfont: { color: '#ffffff', size: 14 },
            outsidetextfont: { color: '#202522', size: 14 },
            cliponaxis: false,
            name: '',
            hovertemplate: '%{y}<br> %{x}',
            ...data,
          },
        ]}
        layout={
          {
            height,
            xaxis: { visible: false, fixedrange: true, ...xaxis },
            yaxis: { fixedrange: true, ...yaxis },
            ...plotlyLayout,
          }
        }
        config={plotlyConfig}
        {...plotlyProps}
      />
    </div>
  )
}

export default Barplot
